import React, { Fragment, useState } from 'react';
import { Outlet } from 'react-router-dom';
import { Disclosure, Menu, Transition } from '@headlessui/react';
import { Bars3Icon, BellIcon, XMarkIcon } from '@heroicons/react/24/outline';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useBranding } from '../contexts/BrandingContext';

import { useNotifications } from '../hooks/useNotifications';
import NotificationBadge from './NotificationBadge';

function classNames(...classes) {
  return classes.filter(Boolean).join(' ');
}

export default function Layout() {
  const { user, logout, isVA, isBusiness } = useAuth();
  const { branding, loading: brandingLoading } = useBranding();
  const navigate = useNavigate();
  const { unreadCount } = useNotifications();
  const [isHoveringBell, setIsHoveringBell] = useState(false);

  // Show loading spinner while branding context is loading
  if (brandingLoading || !branding) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  const navigation = [
    { name: 'Home', href: '/', current: false },
    { name: 'How It Works', href: '/how-it-works', current: false },
    { name: 'Pricing', href: '/pricing', current: false },
    { name: 'Virtual Assistants', href: '/vas', current: false },
    ...(!branding.isESystemsMode ? [{ name: 'Community', href: '/community', current: false }] : []),
    { name: 'About', href: '/about', current: false },
  ];

  const userNavigation = [
    { name: 'Dashboard', href: '/dashboard' },
    { name: 'Profile', href: branding.isESystemsMode ? '/business/profile' : (user?.role === 'va' ? '/va/profile' : '/business/profile') },
    { name: 'Conversations', href: '/conversations' },
    ...(user?.admin ? [{ name: 'Admin Panel', href: '/admin' }] : []),
  ];

  return (
    <div className="min-h-full">
      <Disclosure as="nav" className={classNames(
        branding.isESystemsMode ? "bg-primary-700" : "bg-white border-b border-gray-200",
        "shadow"
      )}>
        {({ open }) => (
          <>
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
              <div className="flex justify-between h-16">
                <div className="flex">
                  <div className="flex-shrink-0 flex items-center">
                    <Link to="/" className="flex items-center">
                      <img
                        className={classNames(
                          "h-9 w-auto",
                          branding.isESystemsMode && "brightness-0 invert"
                        )}
                        src={branding.logoUrl || branding.logo}
                        alt={branding.name}
                      />
                    </Link>
                  </div>
                  <div className="hidden sm:ml-6 sm:flex sm:space-x-8">
                    {navigation.map((item) => (
                      <Link
                        key={item.name}
                        to={item.href}
                        className={classNames(
                          item.current
                            ? branding.isESystemsMode ? 'border-white text-white' : 'border-gray-900 text-gray-900'
                            : branding.isESystemsMode ? 'border-transparent text-white hover:border-white hover:text-gray-200' : 'border-transparent text-gray-700 hover:border-gray-300 hover:text-gray-700',
                          'inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium'
                        )}
                      >
                        {item.name}
                      </Link>
                    ))}
                  </div>
                </div>
                <div className="hidden sm:ml-6 sm:flex sm:items-center">
                  {user ? (
                    <>
                      <button
                        type="button"
                        onClick={() => navigate('/notifications')}
                        onMouseEnter={() => setIsHoveringBell(true)}
                        onMouseLeave={() => setIsHoveringBell(false)}
                        className={classNames(
                          branding.isESystemsMode
                            ? "bg-primary-800 text-white hover:text-gray-200 focus:ring-offset-primary-700 focus:ring-white"
                            : "bg-gray-100 text-gray-700 hover:text-gray-700 focus:ring-offset-2 focus:ring-gray-500",
                          "p-1 rounded-full focus:outline-none focus:ring-2 focus:ring-offset-2 transition-all duration-200",
                          isHoveringBell ? "transform scale-110" : "transform scale-100"
                        )}
                      >
                        <span className="sr-only">View notifications {unreadCount > 0 ? `(${unreadCount} unread)` : ''}</span>
                        <BellIcon 
                          className={classNames(
                            "h-6 w-6 transition-all duration-200",
                            unreadCount > 0 && "animate-wiggle"
                          )} 
                          aria-hidden="true" 
                        />
                        <NotificationBadge count={unreadCount} />
                      </button>

                      {/* Profile dropdown */}
                      <Menu as="div" className="ml-3 relative">
                        <div>
                          <Menu.Button className={classNames(
                            branding.isESystemsMode 
                              ? "bg-primary-800 focus:ring-offset-primary-700 focus:ring-white"
                              : "bg-gray-200 focus:ring-offset-2 focus:ring-gray-500",
                            "rounded-full flex text-sm focus:outline-none focus:ring-2 focus:ring-offset-2"
                          )}>
                            <span className="sr-only">Open user menu</span>
                            <div className={classNames(
                              branding.isESystemsMode ? "bg-primary-600 border-2 border-white" : "bg-gray-400",
                              "h-8 w-8 rounded-full flex items-center justify-center"
                            )}>
                              <span className={classNames(
                                branding.isESystemsMode ? "text-white" : "text-white",
                                "text-sm font-medium"
                              )}>
                                {user.email[0].toUpperCase()}
                              </span>
                            </div>
                          </Menu.Button>
                        </div>
                        <Transition
                          as={Fragment}
                          enter="transition ease-out duration-200"
                          enterFrom="transform opacity-0 scale-95"
                          enterTo="transform opacity-100 scale-100"
                          leave="transition ease-in duration-75"
                          leaveFrom="transform opacity-100 scale-100"
                          leaveTo="transform opacity-0 scale-95"
                        >
                          <Menu.Items className="origin-top-right absolute right-0 mt-2 w-48 rounded-md shadow-lg py-1 bg-white ring-1 ring-black ring-opacity-5 focus:outline-none z-50">
                            {userNavigation.map((item) => (
                              <Menu.Item key={item.name}>
                                {({ active }) => (
                                  <Link
                                    to={item.href}
                                    className={classNames(
                                      active ? 'bg-gray-100' : '',
                                      'block px-4 py-2 text-sm text-gray-700'
                                    )}
                                  >
                                    {item.name}
                                  </Link>
                                )}
                              </Menu.Item>
                            ))}
                            <Menu.Item>
                              {({ active }) => (
                                <button
                                  onClick={logout}
                                  className={classNames(
                                    active ? 'bg-gray-100' : '',
                                    'block w-full text-left px-4 py-2 text-sm text-gray-700'
                                  )}
                                >
                                  Sign out
                                </button>
                              )}
                            </Menu.Item>
                          </Menu.Items>
                        </Transition>
                      </Menu>
                    </>
                  ) : (
                    <div className="flex items-center space-x-4">
                      <Link
                        to="/sign-in"
                        className={classNames(
                          branding.isESystemsMode 
                            ? "text-white hover:text-gray-200"
                            : "text-gray-700 hover:text-gray-900",
                          "px-3 py-2 text-sm font-medium"
                        )}
                      >
                        Sign in
                      </Link>
                      <Link
                        to="/sign-up"
                        className={classNames(
                          branding.isESystemsMode
                            ? "bg-accent-500 hover:bg-accent-600 text-white"
                            : "bg-accent-500 hover:bg-accent-600 text-white",
                          "px-3 py-2 rounded-md text-sm font-medium"
                        )}
                      >
                        Get started
                      </Link>
                    </div>
                  )}
                </div>
                <div className="-mr-2 flex items-center sm:hidden">
                  <Disclosure.Button className={classNames(
                    branding.isESystemsMode 
                      ? "bg-primary-800 text-primary-400 hover:text-white hover:bg-primary-600 focus:ring-offset-primary-700 focus:ring-white"
                      : "bg-gray-100 text-gray-700 hover:text-gray-700 hover:bg-gray-200 focus:ring-offset-2 focus:ring-gray-500",
                    "inline-flex items-center justify-center p-2 rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2"
                  )}>
                    <span className="sr-only">Open main menu</span>
                    {open ? (
                      <XMarkIcon className="block h-6 w-6" aria-hidden="true" />
                    ) : (
                      <Bars3Icon className="block h-6 w-6" aria-hidden="true" />
                    )}
                  </Disclosure.Button>
                </div>
              </div>
            </div>

            <Disclosure.Panel className={classNames(
              "sm:hidden",
              branding.isESystemsMode ? "bg-primary-700" : "bg-white border-b border-gray-200"
            )}>
              <div className="pt-2 pb-3 space-y-1">
                {navigation.map((item) => (
                  <Disclosure.Button
                    key={item.name}
                    as={Link}
                    to={item.href}
                    className={classNames(
                      item.current
                        ? branding.isESystemsMode ? 'bg-primary-800 border-white text-white' : 'bg-gray-50 border-gray-900 text-gray-900'
                        : branding.isESystemsMode ? 'border-transparent text-white hover:bg-primary-600 hover:border-white hover:text-gray-200' : 'border-transparent text-gray-700 hover:bg-gray-50 hover:border-gray-300 hover:text-gray-800',
                      'block pl-3 pr-4 py-2 border-l-4 text-base font-medium'
                    )}
                  >
                    {item.name}
                  </Disclosure.Button>
                ))}
              </div>
              {user ? (
                <div className={classNames(
                  "pt-4 pb-3 border-t",
                  branding.isESystemsMode ? "border-primary-600" : "border-gray-200"
                )}>
                  <div className="flex items-center px-4">
                    <div className="flex-shrink-0">
                      <div className={classNames(
                        branding.isESystemsMode ? "bg-primary-600 border-2 border-white" : "bg-gray-400",
                        "h-10 w-10 rounded-full flex items-center justify-center"
                      )}>
                        <span className={classNames(
                          branding.isESystemsMode ? "text-white" : "text-white",
                          "text-sm font-medium"
                        )}>
                          {user.email[0].toUpperCase()}
                        </span>
                      </div>
                    </div>
                    <div className="ml-3 flex-1">
                      <div className={classNames(
                        branding.isESystemsMode ? "text-white" : "text-gray-900",
                        "text-base font-medium"
                      )}>{user.email}</div>
                    </div>
                    <button
                      onClick={() => navigate('/notifications')}
                      className={classNames(
                        branding.isESystemsMode 
                          ? "bg-primary-800 text-white hover:text-gray-200"
                          : "bg-gray-100 text-gray-700 hover:text-gray-700",
                        "p-2 rounded-full relative mr-2"
                      )}
                    >
                      <span className="sr-only">View notifications {unreadCount > 0 ? `(${unreadCount} unread)` : ''}</span>
                      <BellIcon className="h-6 w-6" aria-hidden="true" />
                      <NotificationBadge count={unreadCount} />
                    </button>
                  </div>
                  <div className="mt-3 space-y-1">
                    {userNavigation.map((item) => (
                      <Disclosure.Button
                        key={item.name}
                        as={Link}
                        to={item.href}
                        className={classNames(
                          branding.isESystemsMode 
                            ? "text-white hover:text-gray-200 hover:bg-primary-600"
                            : "text-gray-700 hover:text-gray-900 hover:bg-gray-100",
                          "block px-4 py-2 text-base font-medium"
                        )}
                      >
                        {item.name}
                      </Disclosure.Button>
                    ))}
                    <Disclosure.Button
                      as="button"
                      onClick={logout}
                      className={classNames(
                        branding.isESystemsMode 
                          ? "text-white hover:text-gray-200 hover:bg-primary-600"
                          : "text-gray-700 hover:text-gray-900 hover:bg-gray-100",
                        "block w-full text-left px-4 py-2 text-base font-medium"
                      )}
                    >
                      Sign out
                    </Disclosure.Button>
                  </div>
                </div>
              ) : (
                <div className={classNames(
                  "pt-4 pb-3 border-t",
                  branding.isESystemsMode ? "border-primary-600" : "border-gray-200"
                )}>
                  <div className="space-y-1">
                    <Disclosure.Button
                      as={Link}
                      to="/sign-in"
                      className="block px-4 py-2 text-base font-medium text-white hover:text-gray-200 hover:bg-primary-600"
                    >
                      Sign in
                    </Disclosure.Button>
                    <Disclosure.Button
                      as={Link}
                      to="/sign-up"
                      className="block px-4 py-2 text-base font-medium text-white bg-accent-500 hover:bg-accent-600 rounded-md mx-4 text-center"
                    >
                      Get started
                    </Disclosure.Button>
                  </div>
                </div>
              )}
            </Disclosure.Panel>
          </>
        )}
      </Disclosure>

      <main className="flex-1">
        <Outlet />
      </main>

      <footer className="bg-white">        
        <div className="max-w-7xl mx-auto py-12 px-4 sm:px-6 lg:px-8">
          <div className="md:flex md:items-center md:justify-between">
            <div className="flex justify-center md:order-2">
              <div className="flex space-x-6">
                <Link to="/terms" className="text-gray-700 hover:text-gray-700 text-sm">
                  Terms of Service
                </Link>
                <Link to="/privacy" className="text-gray-700 hover:text-gray-700 text-sm">
                  Privacy Policy
                </Link>
                <a href="#" className="text-gray-700 hover:text-gray-700">
                  <span className="sr-only">Twitter</span>
                  <svg className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                    <path d="M8.29 20.251c7.547 0 11.675-6.253 11.675-11.675 0-.178 0-.355-.012-.53A8.348 8.348 0 0022 5.92a8.19 8.19 0 01-2.357.646 4.118 4.118 0 001.804-2.27 8.224 8.224 0 01-2.605.996 4.107 4.107 0 00-6.993 3.743 11.65 11.65 0 01-8.457-4.287 4.106 4.106 0 001.27 5.477A4.072 4.072 0 012.8 9.713v.052a4.105 4.105 0 003.292 4.022 4.095 4.095 0 01-1.853.07 4.108 4.108 0 003.834 2.85A8.233 8.233 0 012 18.407a11.616 11.616 0 006.29 1.84" />
                  </svg>
                </a>
              </div>
            </div>
            <div className="mt-8 md:mt-0 md:order-1">
              <p className="text-center text-base text-gray-700">
                &copy; 2025 {branding.name}. All rights reserved.
              </p>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
}